using System;using System.Collections.Generic;using System.Linq;using System.Net;using System.Threading;using System.Threading.Tasks;using System.Web.Http;using AlKhayal.Api.Contracts;using AlKhayal.Application.Authentication;using AlKhayal.Application.Delivery;using AlKhayal.Application.Features;using AlKhayal.Application.Users;using AlKhayal.Core.Models;
namespace AlKhayal.Api.Controllers
{
 [RoutePrefix("api/delivery")] public sealed class DeliveryController:ApiController
 { readonly DeliveryService service;readonly AuthService auth;readonly UserManagementService users;readonly FeatureService features; public DeliveryController(DeliveryService service,AuthService auth,UserManagementService users,FeatureService features){this.service=service;this.auth=auth;this.users=users;this.features=features;}
  [HttpGet,Route("drivers")] public async Task<IHttpActionResult> Drivers(string search="",bool activeOnly=false,CancellationToken ct=default(CancellationToken)){var a=await Require("drivers-management",false,ct).ConfigureAwait(false);if(a!=null)return a;return await Run(ct,async()=>Ok(ApiEnvelope<IReadOnlyList<Driver>>.Ok(await service.DriversAsync(search,activeOnly,ct).ConfigureAwait(false))));}
  [HttpPost,Route("drivers")] public async Task<IHttpActionResult> Save(Driver driver,CancellationToken ct){var a=await Require("drivers-management",true,ct).ConfigureAwait(false);if(a!=null)return a;return await Run(ct,async()=>Ok(ApiEnvelope<Driver>.Ok(await service.SaveDriverAsync(driver,ct).ConfigureAwait(false))));}
  [HttpGet,Route("orders")] public async Task<IHttpActionResult> Orders(string search="",string status="",long? driverId=null,int page=1,int pageSize=25,CancellationToken ct=default(CancellationToken)){var a=await Require("delivery-orders",false,ct).ConfigureAwait(false);if(a!=null)return a;return await Run(ct,async()=>Ok(ApiEnvelope<DeliveryPage>.Ok(await service.OrdersAsync(search,status,driverId,page,pageSize,ct).ConfigureAwait(false))));}
  [HttpPost,Route("orders/{invoiceId:long}/status")] public async Task<IHttpActionResult> Status(long invoiceId,DeliveryStatusRequest request,CancellationToken ct){var a=await Require("delivery-orders",true,ct).ConfigureAwait(false);if(a!=null)return a;return await Run(ct,async()=>{await service.SetStatusAsync(invoiceId,request==null?null:request.Status,ct).ConfigureAwait(false);return Ok(ApiEnvelope<object>.Ok(new{updated=true}));});}
  async Task<IHttpActionResult> Require(string screen,bool write,CancellationToken ct){var token=Cookie();var u=await auth.GetCurrentUserAsync(token,ct).ConfigureAwait(false);if(u==null)return Content(HttpStatusCode.Unauthorized,ApiEnvelope<object>.Fail("unauthorized","يرجى تسجيل الدخول أولًا."));if(u.Role!=UserRoles.Administrator){var access=await users.GetEffectiveAccessAsync(u,await features.GetEffectiveAsync(ct).ConfigureAwait(false),ct).ConfigureAwait(false);if(!access.ScreenIds.Contains(screen,StringComparer.OrdinalIgnoreCase))return Content(HttpStatusCode.Forbidden,ApiEnvelope<object>.Fail("screen_forbidden","لا تملك صلاحية هذه الشاشة."));}if(write&&!await auth.ValidateCsrfAsync(token,Header("X-CSRF-Token"),ct).ConfigureAwait(false))return Content(HttpStatusCode.Forbidden,ApiEnvelope<object>.Fail("invalid_csrf","تعذر التحقق من الطلب."));return null;}
  async Task<IHttpActionResult> Run(CancellationToken ct,Func<Task<IHttpActionResult>> action){try{return await action().ConfigureAwait(false);}catch(ArgumentException e){return Content(HttpStatusCode.BadRequest,ApiEnvelope<object>.Fail("validation",e.Message));}}
  string Cookie(){IEnumerable<string> v;if(!Request.Headers.TryGetValues("Cookie",out v))return null;foreach(var h in v)foreach(var p in h.Split(';')){var x=p.Trim().Split(new[]{'='},2);if(x.Length==2&&x[0]=="alkhayal_session")return x[1];}return null;}string Header(string n){IEnumerable<string> v;return Request.Headers.TryGetValues(n,out v)?v.FirstOrDefault():null;}
 }
 public sealed class DeliveryStatusRequest{public string Status{get;set;}}
}
